export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const mass = inputs.mass;

  const tMax = (2 * launchSpeed) / gravity;
  const clampedTime = Math.max(0, Math.min(tMax, time));

  const height = launchSpeed * clampedTime - 0.5 * gravity * clampedTime * clampedTime;
  const velocity = launchSpeed - gravity * clampedTime;
  const acceleration = -gravity;
  const force = mass * gravity;

  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  let motionState = "Ready to toss";
  if (clampedTime > 0 && clampedTime < apexTime - 0.02) {
    motionState = "Rising";
  } else if (Math.abs(clampedTime - apexTime) <= 0.02) {
    motionState = "At the top";
  } else if (clampedTime > apexTime + 0.02 && clampedTime < tMax) {
    motionState = "Falling";
  } else if (clampedTime >= tMax) {
    motionState = "Back at launch height";
  }

  const objects = [];

  objects.push(...sdk.panel({
    x: 20,
    y: 35,
    w: 285,
    h: 340,
    title: "The motion",
    state: motionState,
    id: "lane.toss"
  }));

  const maxDisplayHeight = Math.max(2.2, apexHeight * 1.2);
  objects.push(sdk.axis("axis.height", {
    x: 50,
    y: 335,
    length: 240,
    orientation: "y",
    min: 0,
    max: maxDisplayHeight,
    ticks: [0, maxDisplayHeight / 2, maxDisplayHeight],
    label: "Height",
    unit: "m"
  }));

  const pxPerM = 240 / maxDisplayHeight;
  const ballY = 335 - height * pxPerM;
  const ballX = 140;

  objects.push(sdk.circle("ball.toss", ballX, ballY, 24, { role: "output" }));

  if (Math.abs(velocity) > 0.01) {
    objects.push(sdk.vector("vec.v", { x: ballX + 20, y: ballY }, { value: velocity, direction: "up" }, { scale: 15, minLength: 12, label: "v", role: "output" }));
  }
  objects.push(sdk.vector("vec.a", { x: ballX - 25, y: ballY }, { value: acceleration, direction: "up" }, { scale: 15, minLength: 12, label: "a", role: "prediction" }));

  const calloutLines = [
    `v: ${velocity.toFixed(2)} m/s`,
    `a: ${acceleration.toFixed(2)} m/s^2`,
    `Fg: ${force.toFixed(1)} N`
  ];
  objects.push(...sdk.callout(ballX + 45, ballY - 20, calloutLines, { id: "callout.toss" }));

  const vtPoints = [];
  const steps = 20;
  for (let i = 0; i <= steps; i++) {
    const tEval = (i / steps) * tMax;
    const vEval = launchSpeed - gravity * tEval;
    vtPoints.push([tEval, vEval]);
  }

  const maxT = Math.max(1.8, tMax);
  objects.push(sdk.plot("plot.vt", {
    x: 330,
    y: 35,
    w: 290,
    h: 340,
    axes: {
      x: { label: "Time", min: 0, max: maxT, unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      { label: "v(t)", kind: "line", points: vtPoints.filter(p => p[0] <= clampedTime) }
    ],
    marker: { x: clampedTime, y: velocity, label: "t", role: "output" }
  }));

  objects.push(sdk.text("plot.vt.note", 350, 360, "Slope a = -g", { role: "neutral" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "velocity", value: velocity },
        { id: "acceleration", value: acceleration },
        { id: "force", value: force },
        { id: "motionState", value: motionState }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      mass,
      apexTime,
      apexHeight,
      height,
      velocity,
      acceleration,
      force
    }
  };
}
